/**
 * SwipeCity Admin Dashboard
 * Pre-production data management and monitoring
 */

import React, { useState, useEffect } from 'react';
import { DataService } from '../utils/dataIntegration';
import { 
  seedQuickDemo, 
  seedFullPreProduction, 
  generateSampleListings, 
  generateSampleUsers 
} from '../utils/dataSeeding';

const AdminDashboard = ({ onClose }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [stats, setStats] = useState({
    users: 0,
    listings: 0,
    interests: 0,
    reports: 0
  });
  const [seedingProgress, setSeedingProgress] = useState('');
  const [recentActivity, setRecentActivity] = useState([]);

  // Load dashboard stats
  useEffect(() => {
    loadDashboardStats();
    loadRecentActivity();
  }, []);

  const loadDashboardStats = async () => {
    try {
      // Get counts from Firebase (implement these methods in DataService)
      const [usersCount, listingsCount, interestsCount, reportsCount] = await Promise.all([
        DataService.getUserCount?.() || 0,
        DataService.getListingCount?.() || 0,
        DataService.getInterestCount?.() || 0,
        DataService.getReportCount?.() || 0
      ]);

      setStats({
        users: usersCount,
        listings: listingsCount,
        interests: interestsCount,
        reports: reportsCount
      });
    } catch (error) {
      console.error('Failed to load stats:', error);
    }
  };

  const loadRecentActivity = async () => {
    try {
      // Get recent activity (implement this method in DataService)
      const activity = await DataService.getRecentActivity?.() || [];
      setRecentActivity(activity.slice(0, 10)); // Last 10 activities
    } catch (error) {
      console.error('Failed to load activity:', error);
    }
  };

  const handleQuickSeed = async () => {
    setIsLoading(true);
    setSeedingProgress('Starting quick demo seeding...');

    try {
      const result = await seedQuickDemo();

      // Debug logging
      console.log('🐛 Seeding result:', result);

      if (result.success) {
        setSeedingProgress(`✅ Created ${result.stats.users} users and ${result.stats.listings} listings successfully!`);

        // Debug current stats before update
        console.log('🐛 Current stats before update:', stats);
        console.log('🐛 Adding:', result.stats);

        // Update stats immediately with the seeded data
        setStats(prevStats => {
          const newStats = {
            users: prevStats.users + (result.stats.users || 0),
            listings: prevStats.listings + (result.stats.listings || 0),
            interests: prevStats.interests + (result.stats.interests || 0),
            reports: prevStats.reports
          };
          console.log('🐛 New stats after update:', newStats);
          return newStats;
        });

        // Don't call loadDashboardStats() here as it resets to 0 - we're using local tracking
      } else {
        setSeedingProgress(`❌ Seeding failed: ${result.error}`);
      }
    } catch (error) {
      console.error('🐛 Seeding error:', error);
      setSeedingProgress(`❌ Error: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleFullSeed = async () => {
    setIsLoading(true);
    setSeedingProgress('Starting full pre-production seeding...');

    try {
      const result = await seedFullPreProduction();
      if (result.success) {
        setSeedingProgress(`✅ Created ${result.stats.users} users, ${result.stats.listings} listings, ${result.stats.interests} interests!`);

        // Update stats immediately with the seeded data
        setStats(prevStats => ({
          users: prevStats.users + (result.stats.users || 0),
          listings: prevStats.listings + (result.stats.listings || 0),
          interests: prevStats.interests + (result.stats.interests || 0),
          reports: prevStats.reports
        }));

        // Also try to load from backend in case there's real data
        await loadDashboardStats();
      } else {
        setSeedingProgress(`❌ Seeding failed: ${result.error}`);
      }
    } catch (error) {
      setSeedingProgress(`❌ Error: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClearData = async () => {
    if (!window.confirm('⚠️ This will delete ALL data. Are you sure?')) return;

    setIsLoading(true);
    setSeedingProgress('Clearing all data...');

    try {
      // Implement bulk delete methods in DataService
      await DataService.clearAllData?.();
      setSeedingProgress('✅ All data cleared successfully!');

      // Reset stats to zero
      setStats({
        users: 0,
        listings: 0,
        interests: 0,
        reports: 0
      });

      await loadDashboardStats();
    } catch (error) {
      setSeedingProgress(`❌ Failed to clear data: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{ 
      position: 'fixed', 
      top: 0, 
      left: 0, 
      right: 0, 
      bottom: 0, 
      background: 'white', 
      zIndex: 10000,
      overflow: 'auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
        {/* Header */}
        <div style={{ marginBottom: '30px', borderBottom: '2px solid #e5e7eb', paddingBottom: '20px', position: 'relative' }}>
          <h1 style={{ 
            margin: 0, 
            color: '#1f2937', 
            fontSize: '28px', 
            fontWeight: 'bold' 
          }}>
            🛠️ SwipeCity Admin Dashboard
          </h1>
          <p style={{ 
            margin: '5px 0 0 0', 
            color: '#6b7280', 
            fontSize: '16px' 
          }}>
            Pre-production data management and monitoring
          </p>
          <button
            onClick={onClose}
            style={{
              position: 'absolute',
              top: '0',
              right: '0',
              background: '#ef4444',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '8px 16px',
              fontSize: '14px',
              cursor: 'pointer',
              fontWeight: '500'
            }}
          >
            Close Dashboard
          </button>
        </div>

        {/* Stats Cards */}
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', 
          gap: '20px', 
          marginBottom: '30px' 
        }}>
          <StatCard title="Users" value={stats.users} icon="👥" color="#3b82f6" />
          <StatCard title="Listings" value={stats.listings} icon="📦" color="#10b981" />
          <StatCard title="Interests" value={stats.interests} icon="💝" color="#f59e0b" />
          <StatCard title="Reports" value={stats.reports} icon="🚨" color="#ef4444" />
        </div>

        {/* Data Seeding Section */}
        <div style={{ 
          background: '#f9fafb', 
          border: '1px solid #e5e7eb', 
          borderRadius: '8px', 
          padding: '25px', 
          marginBottom: '30px' 
        }}>
          <h2 style={{ 
            margin: '0 0 15px 0', 
            color: '#1f2937', 
            fontSize: '20px', 
            fontWeight: '600' 
          }}>
            🌱 Data Seeding
          </h2>

          <div style={{ display: 'flex', gap: '15px', marginBottom: '20px', flexWrap: 'wrap' }}>
            <button
              onClick={handleQuickSeed}
              disabled={isLoading}
              style={{
                padding: '12px 24px',
                background: '#3b82f6',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                fontSize: '14px',
                fontWeight: '500',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                opacity: isLoading ? 0.6 : 1
              }}
            >
              Quick Demo (20 listings)
            </button>

            <button
              onClick={handleFullSeed}
              disabled={isLoading}
              style={{
                padding: '12px 24px',
                background: '#10b981',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                fontSize: '14px',
                fontWeight: '500',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                opacity: isLoading ? 0.6 : 1
              }}
            >
              Full Pre-Production (200 listings)
            </button>

            <button
              onClick={handleClearData}
              disabled={isLoading}
              style={{
                padding: '12px 24px',
                background: '#ef4444',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                fontSize: '14px',
                fontWeight: '500',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                opacity: isLoading ? 0.6 : 1
              }}
            >
              Clear All Data
            </button>
          </div>

          {seedingProgress && (
            <div style={{
              padding: '15px',
              background: seedingProgress.includes('❌') ? '#fef2f2' : '#f0f9ff',
              border: `1px solid ${seedingProgress.includes('❌') ? '#fecaca' : '#bfdbfe'}`,
              borderRadius: '6px',
              color: seedingProgress.includes('❌') ? '#dc2626' : '#1e40af',
              fontSize: '14px',
              fontFamily: 'monospace'
            }}>
              {seedingProgress}
            </div>
          )}
        </div>

        {/* Recent Activity */}
        <div style={{ 
          background: 'white', 
          border: '1px solid #e5e7eb', 
          borderRadius: '8px', 
          padding: '25px' 
        }}>
          <h2 style={{ 
            margin: '0 0 20px 0', 
            color: '#1f2937', 
            fontSize: '20px', 
            fontWeight: '600' 
          }}>
            📊 Recent Activity
          </h2>

          {recentActivity.length > 0 ? (
            <div style={{ space: '10px' }}>
              {recentActivity.map((activity, index) => (
                <div key={index} style={{
                  padding: '12px',
                  background: '#f9fafb',
                  border: '1px solid #f3f4f6',
                  borderRadius: '6px',
                  marginBottom: '8px',
                  fontSize: '14px',
                  color: '#374151'
                }}>
                  <span style={{ fontWeight: '500' }}>{activity.type}</span>
                  {' - '}
                  <span>{activity.description}</span>
                  <span style={{ 
                    float: 'right', 
                    color: '#9ca3af', 
                    fontSize: '12px' 
                  }}>
                    {activity.timestamp}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div style={{ 
              textAlign: 'center', 
              color: '#9ca3af', 
              fontSize: '14px', 
              padding: '40px' 
            }}>
              No recent activity to display
            </div>
          )}
        </div>

        {/* Quick Actions */}
        <div style={{ 
          marginTop: '30px', 
          padding: '20px', 
          background: '#f8fafc', 
          borderRadius: '8px', 
          border: '1px solid #e2e8f0' 
        }}>
          <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '16px' }}>
            ⚡ Quick Actions
          </h3>
          <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
            <QuickActionButton 
              label="Refresh Stats" 
              onClick={loadDashboardStats}
              disabled={isLoading}
            />
            <QuickActionButton 
              label="Export Data" 
              onClick={() => alert('Export functionality coming soon!')}
              disabled={isLoading}
            />
            <QuickActionButton 
              label="View Logs" 
              onClick={() => alert('Log viewer coming soon!')}
              disabled={isLoading}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

// Helper Components
const StatCard = ({ title, value, icon, color }) => (
  <div style={{
    background: 'white',
    border: '1px solid #e5e7eb',
    borderRadius: '8px',
    padding: '20px',
    textAlign: 'center'
  }}>
    <div style={{ fontSize: '24px', marginBottom: '8px' }}>{icon}</div>
    <div style={{ 
      fontSize: '28px', 
      fontWeight: 'bold', 
      color: color, 
      marginBottom: '4px' 
    }}>
      {value.toLocaleString()}
    </div>
    <div style={{ fontSize: '14px', color: '#6b7280' }}>{title}</div>
  </div>
);

const QuickActionButton = ({ label, onClick, disabled }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    style={{
      padding: '8px 16px',
      background: '#f1f5f9',
      color: '#475569',
      border: '1px solid #cbd5e1',
      borderRadius: '4px',
      fontSize: '13px',
      cursor: disabled ? 'not-allowed' : 'pointer',
      opacity: disabled ? 0.6 : 1
    }}
  >
    {label}
  </button>
);

export default AdminDashboard;
